        "factor": "Altman Z-score distress signal (~0.38)",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Distress zone signaling elevates bankruptcy probability in ULCC peers; adds non-negligible risk pressure."
      },
      {
        "factor": "Frontier withdrawal of 2025 guidance",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Increased uncertainty about liquidity and outlook; nudges probability higher."
      },
      {
        "factor": "Spirit Airlines bankruptcy context and Frontier bid dynamics",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Industry stress and competitive dynamics elevate near-term vulnerability but are not a direct indicator of Frontier filing."
      }
